const detailJobs=new Map();let reserveJob=null;
async function ensureCountyDetail(id){
 if(!ATLAS_ASSETS.detail[id])return;
 if(!detailJobs.has(id))detailJobs.set(id,loadAtlasAsset(ATLAS_ASSETS.detail[id]).then(paths=>{
  for(const c of provinceRows.get(id)||[]){if(paths[c.id]){c.path=paths[c.id];if(mode==='county')$('regions').querySelector('[data-id="'+c.id+'"]')?.setAttribute('d',c.path);}}
  sizeRelationMarks();if(mode==='county'&&selected?.pid===id)fitSelection();return true;
 }).catch(()=>{detailJobs.delete(id);$('geometryStatus').textContent='当前显示概览边界；再次选择可重试精细县界。';return false;}));
 return detailJobs.get(id);
}
async function ensureReserves(){
 if(reserveJob)return reserveJob;
 $('geometryStatus').textContent='正在载入保护区实际边界…';
 reserveJob=loadAtlasAsset(ATLAS_ASSETS.reserves).then(data=>{reserves.push(...data);$('geometryStatus').textContent='保护区边界已载入';renderOverlays();}).catch(()=>{reserveJob=null;$('geometryStatus').innerHTML='保护区边界暂未载入。<button id="retryReserves">重试</button>';$('retryReserves').onclick=ensureReserves;});return reserveJob;
}
