  let near='当前没有可用的近邻评价记录，先完成本县场址与接入条件调查。';
  if(best){const delta=score-val(best,'score'),fields=[['太阳辐射','radiation'],['坡度条件','slope'],['GDP经济指数','gdp']],largest=fields.map(([name,k])=>({name,k,d:p(k)-percentile(val(best,k),k)})).filter(d=>valid(d.d)).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d))[0];near='近邻中得分最高的是'+best.name+'（'+val(best,'priority')+'级，'+compact(val(best,'score'),'score')+'）；'+(valid(score)?c.name+'的得分'+(delta>=0?'高':'低')+Math.abs(delta).toFixed(6)+'。':'本县综合得分暂缺，暂不比较得分差。');if(largest)near+=' 两县差异较大的是'+largest.name+'：本县'+compact(val(c,largest.k),largest.k)+'，'+best.name+compact(val(best,largest.k),largest.k)+'。';near+='优先比较各自可用场址和实际接入条件，确定试点位置与推进先后。';}
